type presenceResponse struct {
	// Credential is returned exactly once, on creation. Callers retain it only
	// in process memory; renewals and ordinary resident/tool results omit it.
	Credential string       `json:"credential,omitempty"`
	Change     nexus.Change `json:"change"`
}

func (s *Server) handleAnnounce(writer http.ResponseWriter, request *http.Request) {
	var input presenceRequest
	if err := decode(request, &input); err != nil {
		write(writer, nil, err)
		return
	}
	actor, private, err := s.workspace.Actor(input.Actor)
	if err != nil {
		write(writer, nil, err)
		return
	}
	if input.Focus != nil {
		if len(*input.Focus) > nexus.MaxFocusEvents {
			write(writer, nil, errors.New("focus exceeds the eight-event limit"))
			return
		}
		snapshot, snapshotErr := s.workspace.Snapshot(request.Context())
		if snapshotErr != nil {
			write(writer, nil, snapshotErr)
			return
		}
		known := make(map[string]bool, len(snapshot.Projection.Decisions))
		for _, decision := range snapshot.Projection.Decisions {
			known[decision.Event] = true
		}
		for _, event := range *input.Focus {
			if !known[event] {
				write(writer, nil, errors.New("focus must contain only EventIDs from this workroom"))
				return
			}
		}
	}
	ttl := time.Duration(input.TTLMS) * time.Millisecond
	if ttl <= 0 || ttl > 2*time.Minute {
		ttl = 30 * time.Second
	}
	update := nexus.ActivityUpdate{Status: input.Status, Focus: input.Focus, Note: input.Note}
	if input.Session == "" {
		credential, change, err := s.hub.OpenTrustedSession(input.Actor, private.Public().(ed25519.PublicKey), actor.Name+" ("+actor.Fingerprint[:12]+")", ttl, update)
		write(writer, presenceResponse{Credential: credential, Change: change}, err)
		return
	}
	change, err := s.hub.RenewSession(input.Session, input.Actor, private.Public().(ed25519.PublicKey), actor.Name+" ("+actor.Fingerprint[:12]+")", ttl, update)
	write(writer, presenceResponse{Change: change}, err)
}

